export const QUEUE_ACCESS_TOKEN_HEADER = 'x-rivet-queue-token';

export const CALLER_SESSION_HEADER = 'x-rivet-caller-session';

type QueueAccessAuthorization = {
  queueAccessToken?: string | null;
  getHeader: (name: string) => string | string[] | undefined;
};

export const isQueueAccessAuthorized = ({
  queueAccessToken,
  getHeader,
}: QueueAccessAuthorization): boolean => {
  if (!queueAccessToken) {
    return true;
  }
  return getHeader(QUEUE_ACCESS_TOKEN_HEADER) === queueAccessToken;
};
